// Package email renders transactional emails from templates authored in React
// Email (the repo-root emails/ project) and sends them over SMTP.
//
// The templates under templates/ are generated by `npm run build` in emails/:
// each has a .html and a plaintext .txt form whose dynamic values are Go
// template tokens. They are embedded into the binary, so nothing ships
// alongside it. The images they point at live in web/public/email.
package email

import (
	"bytes"
	"context"
	"crypto/rand"
	"crypto/tls"
	"embed"
	"encoding/hex"
	"errors"
	"fmt"
	htmltemplate "html/template"
	"log/slog"
	"mime"
	"mime/multipart"
	"mime/quotedprintable"
	"net"
	"net/mail"
	"net/smtp"
	"net/textproto"
	"strconv"
	"strings"
	texttemplate "text/template"
	"time"
)

//go:embed templates/*.html templates/*.txt
var templatesFS embed.FS

// Message is one of the template data types in data.go.
type Message interface {
	base() *Base
	template() string
	subject() string
}

// Config is what the Mailer needs. Without Host and From it only logs.
type Config struct {
	Host     string
	Port     int // 465 = implicit TLS; anything else uses STARTTLS
	Username string
	Password string
	From     string // address
	FromName string
	AppURL   string
	// AssetsURL serves web/public (images are ${AssetsURL}/email/*.png).
	AssetsURL string
}

// Mailer renders and sends emails. A nil *Mailer is valid and does nothing.
type Mailer struct {
	cfg  Config
	html *htmltemplate.Template
	text *texttemplate.Template
	log  *slog.Logger
	// deliver sends a built message (replaceable in tests).
	deliver func(ctx context.Context, to string, msg []byte) error
}

// New parses the templates up front, so a broken one fails at startup.
func New(cfg Config, log *slog.Logger) *Mailer {
	m := &Mailer{
		cfg:  cfg,
		html: htmltemplate.Must(htmltemplate.ParseFS(templatesFS, "templates/*.html")),
		text: texttemplate.Must(texttemplate.ParseFS(templatesFS, "templates/*.txt")),
		log:  log,
	}
	if cfg.Host != "" && cfg.From != "" {
		m.deliver = m.smtpDeliver
	}
	return m
}

// Enabled reports whether emails actually leave the server.
func (m *Mailer) Enabled() bool { return m != nil && m.deliver != nil }

// Go sends msg in the background, off the request path, and logs the outcome.
func (m *Mailer) Go(to string, msg Message) {
	if m == nil || to == "" {
		return
	}
	go func() {
		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		defer cancel()
		if err := m.Send(ctx, to, msg); err != nil {
			m.log.Warn("email: send failed", "template", msg.template(), "err", err)
		}
	}()
}

// Send renders msg and delivers it as multipart HTML + plaintext. Without SMTP
// configured it still renders (so template errors surface) and only logs.
func (m *Mailer) Send(ctx context.Context, to string, msg Message) error {
	if m == nil {
		return nil
	}
	*msg.base() = Base{AppURL: m.cfg.AppURL, AssetsURL: m.cfg.AssetsURL}
	html, text, err := m.Render(msg)
	if err != nil {
		return err
	}
	if m.deliver == nil {
		m.log.Info("email: skipped, SMTP not configured", "template", msg.template())
		return nil
	}
	raw, err := m.build(to, msg.subject(), html, text)
	if err != nil {
		return err
	}
	if err := m.deliver(ctx, to, raw); err != nil {
		return err
	}
	m.log.Info("email: sent", "template", msg.template())
	return nil
}

// Render returns msg's HTML and plaintext bodies.
func (m *Mailer) Render(msg Message) (html, text string, err error) {
	var h, t bytes.Buffer
	if err := m.html.ExecuteTemplate(&h, msg.template()+".html", msg); err != nil {
		return "", "", err
	}
	if err := m.text.ExecuteTemplate(&t, msg.template()+".txt", msg); err != nil {
		return "", "", err
	}
	return h.String(), t.String(), nil
}

// build writes an RFC 5322 multipart/alternative message.
func (m *Mailer) build(to, subject, html, text string) ([]byte, error) {
	if _, err := mail.ParseAddress(to); err != nil {
		return nil, fmt.Errorf("email: bad recipient: %w", err)
	}
	from := mail.Address{Name: m.cfg.FromName, Address: m.cfg.From}
	var b bytes.Buffer
	mw := multipart.NewWriter(&b)
	id := make([]byte, 16)
	_, _ = rand.Read(id)
	domain := m.cfg.From[strings.LastIndex(m.cfg.From, "@")+1:]
	hdr := []string{
		"From: " + from.String(),
		"To: " + to,
		"Subject: " + mime.QEncoding.Encode("utf-8", subject),
		"Date: " + time.Now().Format(time.RFC1123Z),
		"Message-ID: <" + hex.EncodeToString(id) + "@" + domain + ">",
		"MIME-Version: 1.0",
		"Content-Type: multipart/alternative; boundary=" + mw.Boundary(),
	}
	// The multipart writer hasn't written anything yet, so the headers go first.
	b.WriteString(strings.Join(hdr, "\r\n") + "\r\n\r\n")
	for _, part := range []struct{ typ, body string }{{"text/plain", text}, {"text/html", html}} {
		w, err := mw.CreatePart(textproto.MIMEHeader{
			"Content-Type":              {part.typ + "; charset=utf-8"},
			"Content-Transfer-Encoding": {"quoted-printable"},
		})
		if err != nil {
			return nil, err
		}
		qp := quotedprintable.NewWriter(w)
		if _, err := qp.Write([]byte(part.body)); err != nil {
			return nil, err
		}
		if err := qp.Close(); err != nil {
			return nil, err
		}
	}
	if err := mw.Close(); err != nil {
		return nil, err
	}
	return b.Bytes(), nil
}

// smtpDeliver sends over SMTP: implicit TLS on 465, else STARTTLS, which is
// required unless the server is local (a dev catcher like Mailpit).
func (m *Mailer) smtpDeliver(ctx context.Context, to string, msg []byte) error {
	addr := net.JoinHostPort(m.cfg.Host, strconv.Itoa(m.cfg.Port))
	tlsCfg := &tls.Config{ServerName: m.cfg.Host, MinVersion: tls.VersionTLS12}
	d := &net.Dialer{Timeout: 15 * time.Second}
	var conn net.Conn
	var err error
	if m.cfg.Port == 465 {
		conn, err = (&tls.Dialer{NetDialer: d, Config: tlsCfg}).DialContext(ctx, "tcp", addr)
	} else {
		conn, err = d.DialContext(ctx, "tcp", addr)
	}
	if err != nil {
		return err
	}
	if dl, ok := ctx.Deadline(); ok {
		_ = conn.SetDeadline(dl)
	}
	c, err := smtp.NewClient(conn, m.cfg.Host)
	if err != nil {
		conn.Close()
		return err
	}
	defer c.Close()
	if m.cfg.Port != 465 {
		if ok, _ := c.Extension("STARTTLS"); ok {
			if err := c.StartTLS(tlsCfg); err != nil {
				return err
			}
		} else if !isLocal(m.cfg.Host) {
			return errors.New("email: server doesn't offer STARTTLS")
		}
	}
	if m.cfg.Username != "" {
		if err := c.Auth(smtp.PlainAuth("", m.cfg.Username, m.cfg.Password, m.cfg.Host)); err != nil {
			return err
		}
	}
	if err := c.Mail(m.cfg.From); err != nil {
		return err
	}
	if err := c.Rcpt(to); err != nil {
		return err
	}
	w, err := c.Data()
	if err != nil {
		return err
	}
	if _, err := w.Write(msg); err != nil {
		return err
	}
	if err := w.Close(); err != nil {
		return err
	}
	return c.Quit()
}

func isLocal(host string) bool {
	return host == "localhost" || host == "127.0.0.1" || host == "::1"
}
